const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Cube Collector</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { background: #1a1a2e; overflow: hidden; font-family: 'Arial', sans-serif; }
        #game-container { width: 100vw; height: 100vh; }
        #score { position: fixed; top: 20px; left: 20px; color: #4ecca3; font-size: 24px; font-weight: bold; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); }
        #controls { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); color: #fff; font-size: 16px; text-shadow: 1px 1px 2px rgba(0,0,0,0.7); }
        #game-over { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: rgba(0,0,0,0.9); padding: 40px; border-radius: 10px; text-align: center; color: #fff; font-size: 28px; display: none; }
        #game-over h1 { color: #ff6b6b; margin-bottom: 20px; }
        #restart-btn { background: #4ecca3; border: none; padding: 15px 30px; font-size: 18px; border-radius: 8px; cursor: pointer; margin-top: 20px; color: #1a1a2e; font-weight: bold; }
        #restart-btn:hover { background: #45b092; }
    </style>
</head>
<body>
    <div id="game-container"></div>
    <div id="score">Score: 0</div>
    <div id="controls">Use WASD or Arrow Keys to move | Collect green cubes | Avoid red cubes!</div>
    <div id="game-over">
        <h1>GAME OVER</h1>
        <p id="final-score"></p>
        <button id="restart-btn" onclick="resetGame()">Play Again</button>
    </div>

    <script src="https://unpkg.com/three@0.159.0/build/three.min.js"></script>
    <script>
        // Game Variables
        let scene, camera, renderer;
        let player, ground;
        let coins = [], obstacles = [];
        let score = 0;
        let gameActive = true;
        let spawnRate = 50;
        let frameCount = 0;

        // Player movement
        let moveSpeed = 0.3;
        let keys = { w: false, a: false, s: false, d: false };

        // Scene setup
        function init() {
            const container = document.getElementById('game-container');

            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x1a1a2e);
            scene.fog = new THREE.Fog(0x1a1a2e, 50, 150);

            camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 15, 30);
            camera.lookAt(0, 0, 0);

            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.shadowMap.enabled = true;
            container.appendChild(renderer.domElement);

            // Lighting
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(10, 20, 10);
            directionalLight.castShadow = true;
            scene.add(directionalLight);

            // Ground
            const groundGeometry = new THREE.PlaneGeometry(200, 200);
            const groundMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x2d3436,
                roughness: 0.8,
                metalness: 0.2
            });
            ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = Math.PI / 2;
            scene.add(ground);

            // Grid helper
            const gridHelper = new THREE.GridHelper(200, 50, 0x4ecca3, 0x2d3436);
            scene.add(gridHelper);

            // Player cube
            const playerGeometry = new THREE.BoxGeometry(1, 1, 1);
            const playerMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x4ecca3,
                emissive: 0x2d3436,
                roughness: 0.4,
                metalness: 0.6
            });
            player = new THREE.Mesh(playerGeometry, playerMaterial);
            player.castShadow = true;
            scene.add(player);

            // Input handling
            window.addEventListener('keydown', e => {
                if (keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = true;
            });
            window.addEventListener('keyup', e => {
                if (keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = false;
            });

            window.addEventListener('resize', () => {
                camera.aspect = window.innerWidth / window.innerHeight;
                camera.updateProjectionMatrix();
                renderer.setSize(window.innerWidth, window.innerHeight);
            });

            animate();
        }

        function spawnCoin() {
            const geometry = new THREE.BoxGeometry(0.8, 0.8, 0.8);
            const material = new THREE.MeshStandardMaterial({ 
                color: 0xff6b6b,
                emissive: 0x451a1a,
                roughness: 0.3,
                metalness: 0.7
            });
            const coin = new THREE.Mesh(geometry, material);

            // Spawn in front of player
            const angle = Math.random() * Math.PI * 2;
            const distance = 20 + Math.random() * 10;
            const x = Math.cos(angle) * distance;
            const z = Math.sin(angle) * distance;

            coin.position.set(x, 0.5, z);
            scene.add(coin);
            coins.push(coin);
        }

        function spawnObstacle() {
            const geometry = new THREE.BoxGeometry(1, 1, 1);
            const material = new THREE.MeshStandardMaterial({ 
                color: 0xff6b6b,
                emissive: 0x451a1a,
                roughness: 0.2,
                metalness: 0.8
            });
            const obstacle = new THREE.Mesh(geometry, material);

            // Spawn in front of player at random angle
            const angle = Math.random() * Math.PI * 2;
            const distance = 15 + Math.random() * 15;
            const x = Math.cos(angle) * distance;
            const z = Math.sin(angle) * distance;

            obstacle.position.set(x, 0.5, z);
            scene.add(obstacle);
            obstacles.push(obstacle);
        }

        function checkCollisions() {
            if (!gameActive) return;

            // Check coin collisions
            for (let i = coins.length - 1; i >= 0; i--) {
                const coin = coins[i];
                if (coin.position.distanceTo(player.position) < 1.2) {
                    scene.remove(coin);
                    coins.splice(i, 1);
                    score += 10;
                    document.getElementById('score').textContent = 'Score: ' + score;

                    // Speed up game slightly
                    if (score % 50 === 0) {
                        moveSpeed = Math.min(moveSpeed + 0.02, 0.8);
                    }
                }
            }

            // Check obstacle collisions
            for (let i = obstacles.length - 1; i >= 0; i--) {
                const obstacle = obstacles[i];
                if (obstacle.position.distanceTo(player.position) < 1.2) {
                    gameOver();
                }
            }
        }

        function updatePlayer() {
            player.position.x += keys.w ? moveSpeed : 0;
            player.position.x -= keys.s ? moveSpeed : 0;
            player.position.z += keys.d ? moveSpeed : 0;
            player.position.z -= keys.a ? moveSpeed : 0;

            // Clamp position
            const limit = 90;
            player.position.x = Math.max(-limit, Math.min(limit, player.position.x));
            player.position.z = Math.max(-limit, Math.min(limit, player.position.z));

            // Rotate player based on movement
            const targetRotation = Math.atan2(keys.d ? 1 : 0, keys.w ? -1 : 0);
            player.rotation.y += (targetRotation - player.rotation.y) * 0.2;
        }

        function updateSpawning() {
            frameCount++;
            if (frameCount % spawnRate === 0 && gameActive) {
                spawnCoin();
                // 30% chance for obstacle
                if (Math.random() < 0.3) spawnObstacle();
            }
            // Increase spawn rate over time
            spawnRate = Math.max(20, 50 - Math.floor(score / 10));
        }

        function animate() {
            if (!gameActive) return;

            requestAnimationFrame(animate);

            updatePlayer();
            checkCollisions();
            updateSpawning();

            // Animate coins and obstacles
            coins.forEach(c => c.rotation.x += 0.05);
            obstacles.forEach(o => o.rotation.x += 0.03);

            renderer.render(scene, camera);
        }

        function gameOver() {
            gameActive = false;
            document.getElementById('final-score').textContent = 'Final Score: ' + score;
            document.getElementById('game-over').style.display = 'block';

            // Player animation
            player.position.y = 0.5;
            player.rotation.set(Math.PI / 2, 0, 0);
        }

        function resetGame() {
            // Clear coins and obstacles
            coins.forEach(c => scene.remove(c));
            obstacles.forEach(o => scene.remove(o));
            coins = [];
            obstacles = [];

            score = 0;
            document.getElementById('score').textContent = 'Score: 0';
            moveSpeed = 0.3;

            player.position.set(0, 0, 0);
            player.rotation.y = 0;

            gameActive = true;
            spawnRate = 50;
            frameCount = 0;

            document.getElementById('game-over').style.display = 'none';
            animate();
        }

        // Initialize game
        init();
    </script>
</body>
</html>`;

console.log(html.length);
if (html) {
    console.log("✅ HTML file created successfully!");
    console.log("📊 File size:", html.length, "bytes");
} else {
    console.error("❌ Failed to create HTML file");
}

