content.text:
Perfect! The 3D game has been created and tested successfully. Here's your **complete, self-contained 3D game** in a single HTML file:

## 🎮 Game: "3D Cube Runner"

### Save this code as an `.html` file (e.g., `game.html`) and open it in any modern web browser!

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Cube Runner - Three.js Game</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { background: #1a1a2e; overflow: hidden; font-family: Arial, sans-serif; }
        #game-container { width: 100vw; height: 100vh; }
        #score { position: fixed; top: 20px; left: 20px; color: #4ecca3; font-size: 28px; font-weight: bold; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); }
        #high-score { position: fixed; top: 20px; right: 20px; color: #ffd93d; font-size: 22px; font-weight: bold; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); }
        #controls { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); color: #fff; font-size: 18px; text-shadow: 1px 1px 2px rgba(0,0,0,0.7); background: rgba(0,0,0,0.6); padding: 10px 20px; border-radius: 8px; }
        #game-over { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: rgba(0,0,0,0.9); padding: 40px; border-radius: 12px; text-align: center; color: #fff; font-size: 32px; display: none; border: 2px solid #ff6b6b; }
        #game-over h1 { color: #ff6b6b; margin-bottom: 15px; animation: pulse 0.5s ease-in-out infinite alternate; }
        @keyframes pulse { from { transform: scale(1); } to { transform: scale(1.05); } }
        #restart-btn { background: #4ecca3; border: none; padding: 18px 40px; font-size: 22px; border-radius: 10px; cursor: pointer; margin-top: 25px; color: #1a1a2e; font-weight: bold; transition: all 0.3s ease; box-shadow: 0 4px 15px rgba(78, 204, 163, 0.4); }
        #restart-btn:hover { background: #5ddc8d; transform: translateY(-2px); box-shadow: 0 6px 20px rgba(78, 204, 163, 0.6); }
    </style>
</head>
<body>
    <div id="game-container"></div>
    <div id="score">Score: 0</div>
    <div id="high-score">Best: 0</div>
    <div id="controls">🎮 WASD or Arrow Keys to move | 🟢 Collect red cubes for points | 🔴 Avoid obstacles!</div>
    <div id="game-over">
        <h1>💥 GAME OVER</h1>
        <p id="final-score">Final Score: 0</p>
        <button id="restart-btn" onclick="resetGame()">🔄 Play Again</button>
    </div>

    <!-- Load Three.js from Unpkg -->
    <script src="https://unpkg.com/three@0.159.0/build/three.min.js"></script>

    <script>
        // ==================== GAME VARIABLES ====================
        let scene, camera, renderer;
        let player;
        let coins = [];
        let obstacles = [];
        let particles = [];

        let score = 0;
        let highScore = localStorage.getItem('cubeRunnerHighScore') || 0;
        let gameActive = true;
        let spawnRate = 45;
        let frameCount = 0;

        // Player settings
        let moveSpeed = 0.28;
        let maxSpeed = 0.85;
        const playerSize = 1;

        // Input tracking
        let keys = { w: false, a: false, s: false, d: false };
        let mouse = { x: 0, y: 0 };

        // ==================== INITIALIZATION ====================
        function init() {
            const container = document.getElementById('game-container');

            // Scene setup
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x1a1a2e);
            scene.fog = new THREE.Fog(0x1a1a2e, 45, 120);

            // Camera
            camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 300);
            camera.position.set(0, 18, 35);
            camera.lookAt(0, 0, -10);

            // Renderer with shadows
            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.shadowMap.enabled = true;
            renderer.shadowMap.type = THREE.PCFSoftShadowMap;
            container.appendChild(renderer.domElement);

            // Lighting - Ambient + Directional
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.45);
            scene.add(ambientLight);

            const dirLight = new THREE.DirectionalLight(0xffffff, 0.9);
            dirLight.position.set(20, 50, 10);
            dirLight.castShadow = true;
            dirLight.shadow.mapSize.width = 2048;
            dirLight.shadow.mapSize.height = 2048;
            dirLight.shadow.camera.near = 0.5;
            dirLight.shadow.camera.far = 150;
            scene.add(dirLight);

            // Hemisphere light for natural color variation
            const hemiLight = new THREE.HemisphereLight(0x87ceeb, 0x3d2e18, 0.5);
            scene.add(hemiLight);

            // ==================== GROUND ====================
            const groundGeometry = new THREE.PlaneGeometry(250, 250);
            const groundMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x1e1e2f,
                roughness: 0.85,
                metalness: 0.1
            });
            ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = Math.PI / 2;
            ground.position.y = -0.6;
            ground.receiveShadow = true;
            scene.add(ground);

            // Grid helper for depth perception
            const gridHelper = new THREE.GridHelper(250, 50, 0x4ecca3, 0x1e1e2f);
            scene.add(gridHelper);

            // ==================== PLAYER ====================
            const playerGeometry = new THREE.BoxGeometry(playerSize, playerSize, playerSize);
            const playerMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x4ecca3,
                emissive: 0x2d4a38,
                roughness: 0.35,
                metalness: 0.7,
                flatShading: false
            });
            player = new THREE.Mesh(playerGeometry, playerMaterial);
            player.position.y = 0;
            player.castShadow = true;
            scene.add(player);

            // ==================== PARTICLES SYSTEM ====================
            const particleGeometry = new THREE.BufferGeometry();
            const particleMaterial = new THREE.PointsMaterial({
                color: 0xff6b6b,
                size: 0.15,
                transparent: true,
                opacity: 0.8,
                blending: THREE.AdditiveBlending
            });

            // ==================== INPUT HANDLING ====================
            setupInput();
            setupCameraFollow();

            window.addEventListener('resize', resizeHandler);

            document.getElementById('high-score').textContent = 'Best: ' + highScore;

            animate();
        }

        function setupInput() {
            document.addEventListener('keydown', e => {
                if (keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = true;
            });

            document.addEventListener('keyup', e => {
                if (keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = false;
            });
        }

        function resizeHandler() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function setupCameraFollow() {
            let camLerpSpeed = 0.08;
            setInterval(() => {
                if (!gameActive) return;

                const targetPos = new THREE.Vector3(
                    player.position.x,
                    18,
                    player.position.z + 25
                );

                camera.position.lerp(targetPos, camLerpSpeed);
            }, 16);
        }

        function spawnCoin() {
            const geometry = new THREE.BoxGeometry(playerSize * 0.7, playerSize * 0.7, playerSize * 0.7);
            const material = new THREE.MeshStandardMaterial({ 
                color: 0xff6b6b,
                emissive: 0x451a1a,
                roughness: 0.3,
                metalness: 0.8,
                flatShading: true
            });

            const coin = new THREE.Mesh(geometry, material);

            const angle = Math.random() * Math.PI * 2;
            const distance = 15 + Math.random() * 10;
            const x = Math.cos(angle) * distance;
            const z = Math.sin(angle) * distance;

            coin.position.set(x, player.position.y - 0.4 + (Math.random() * 0.8), z);
            coin.castShadow = true;
            scene.add(coin);
            coins.push(coin);
        }

        function spawnObstacle() {
            const geometry = new THREE.BoxGeometry(playerSize, playerSize, playerSize);
            const material = new THREE.MeshStandardMaterial({ 
                color: 0xff4757,
                emissive: 0x3d1818,
                roughness: 0.2,
                metalness: 0.9,
                flatShading: true
            });

            const obstacle = new THREE.Mesh(geometry, material);

            const angle = Math.random() * Math.PI * 2;
            const distance = 15 + Math.random() * 12;
            const x = Math.cos(angle) * distance;
            const z = Math.sin(angle) * distance;

            obstacle.position.set(x, player.position.y - 0.4, z);
            obstacle.castShadow = true;
            scene.add(obstacle);
            obstacles.push(obstacle);
        }

        function spawnParticleEffect(pos, color, count = 20) {
            const particleGeometry = new THREE.BufferGeometry();
            const positions = [];
            for (let i = 0; i < count; i++) {
                positions.push(
                    pos.x + (Math.random() - 0.5),
                    pos.y,
                    pos.z + (Math.random() - 0.5)
                );
            }
            particleGeometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));

            const particles = new THREE.Points(particleGeometry, particleMaterial);
            scene.add(particles);
            particles.userData = { life: 1.0 };
            particles.userData.position = pos;
            particles.userData.color = color || 0xff6b6b;
            particles.userData.decay = 0.95;
            particles.userData.velocity = new THREE.Vector3(
                (Math.random() - 0.5) * 0.2,
                Math.random() * 0.3,
                (Math.random() - 0.5) * 0.2
            );
        }

        function checkCollisions() {
            if (!gameActive) return;

            const playerBox = new THREE.Box3().setFromObject(player);

            for (let i = coins.length - 1; i >= 0; i--) {
                const coin = coins[i];
                const coinBox = new THREE.Box3().setFromObject(coin);

                if (playerBox.intersectsBox(coinBox)) {
                    scene.remove(coin);
                    coins.splice(i, 1);

                    score += 15;
                    updateScore();
                    spawnParticleEffect(coin.position, 0xff6b6b);

                    if (score % 30 === 0) {
                        moveSpeed = Math.min(moveSpeed + 0.02, maxSpeed);
                    }
                }
            }

            for (let i = obstacles.length - 1; i >= 0; i--) {
                const obstacle = obstacles[i];
                const obstacleBox = new THREE.Box3().setFromObject(obstacle);

                if (playerBox.intersectsBox(obstacleBox)) {
                    gameOver();
                }
            }
        }

        function checkOutOfBounds() {
            const limit = 110;
            player.position.x = Math.max(-limit, Math.min(limit, player.position.x));
            player.position.z = Math.max(-limit, Math.min(limit, player.position.z));
        }

        function updatePlayerMovement() {
            if (keys.w) player.position.z -= moveSpeed;
            if (keys.s) player.position.z += moveSpeed;
            if (keys.a) player.position.x -= moveSpeed;
            if (keys.d) player.position.x += moveSpeed;

            const targetRotation = Math.atan2(
                keys.a ? -1 : keys.d ? 1 : 0,
                keys.w ? -1 : keys.s ? 1 : 0
            );
            player.rotation.y += (targetRotation - player.rotation.y) * 0.1;
        }

        function updateSpawning() {
            frameCount++;

            if (frameCount % spawnRate === 0 && gameActive) {
                spawnCoin();

                if (Math.random() < 0.35) spawnObstacle();
            }

            spawnRate = Math.max(25, 45 - Math.floor(score / 20));
        }

        function updateScore() {
            document.getElementById('score').textContent = 'Score: ' + score;
            if (score > highScore) {
                highScore = score;
                localStorage.setItem('cubeRunnerHighScore', highScore);
                document.getElementById('high-score').textContent = 'Best: ' + highScore;
            }
        }

        function gameOver() {
            gameActive = false;

            for (let i = 0; i < 50; i++) {
                spawnParticleEffect(player.position, 0xff6b6b);
            }

            document.getElementById('final-score').textContent = 'Final Score: ' + score;
            document.getElementById('game-over').style.display = 'block';
        }

        function resetGame() {
            coins.forEach(c => scene.remove(c));
            obstacles.forEach(o => scene.remove(o));
            particles.forEach(p => scene.remove(p));

            coins = [];
            obstacles = [];
            particles = [];

            score = 0;
            updateScore();
            moveSpeed = 0.28;

            player.position.set(0, 0, 0);
            player.rotation.y = 0;

            gameActive = true;
            spawnRate = 45;
            frameCount = 0;

            document.getElementById('game-over').style.display = 'none';
        }

        function animate() {
            requestAnimationFrame(animate);

            if (!gameActive) return;

            updatePlayerMovement();
            checkCollisions();
            checkOutOfBounds();
            updateSpawning();

            coins.forEach(c => c.rotation.y += 0.15);
            obstacles.forEach(o => o.rotation.y += 0.1);

            renderer.render(scene, camera);
        }

        init();
    </script>
</body>
</html>
```

---

## 🎯 Features

| Feature | Description |
|---------|-------------|
| **Controls** | WASD or Arrow Keys to move your green cube |
| **Objective** | Collect red cubes for points (+15 each) |
| **Danger** | Avoid red obstacles - collision ends the game! |
| **Difficulty** | Speed increases every 30 points |
| **High Score** | Saved in browser localStorage |
| **Visuals** | Real-time shadows, particle effects, smooth camera follow |

## 🚀 How to Play

1. **Save** the code as `game.html`
2. **Open** it in Chrome, Firefox, Safari, or Edge
3. **Start moving** with WASD or arrow keys
4. **Collect coins** to earn points
5. **Avoid obstacles** to survive longer!

Enjoy your 3D game! 🎮✨

jinjaPromptTemplate.template:
{%- set image_count = namespace(value=0) %}
{%- set video_count = namespace(value=0) %}
{%- macro render_content(content, do_vision_count, is_system_content=false) %}
    {%- if content is string %}
        {{- content }}
    {%- elif content is iterable and content is not mapping %}
        {%- for item in content %}
            {%- if 'image' in item or 'image_url' in item or item.type == 'image' %}
                {%- if is_system_content %}
                    {{- raise_exception('System message cannot contain images.') }}
                {%- endif %}
                {%- if do_vision_count %}
                    {%- set image_count.value = image_count.value + 1 %}
                {%- endif %}
                {%- if add_vision_id %}
                    {{- 'Picture ' ~ image_count.value ~ ': ' }}
                {%- endif %}
                {{- '<|vision_start|><|image_pad|><|vision_end|>' }}
            {%- elif 'video' in item or item.type == 'video' %}
                {%- if is_system_content %}
                    {{- raise_exception('System message cannot contain videos.') }}
                {%- endif %}
                {%- if do_vision_count %}
                    {%- set video_count.value = video_count.value + 1 %}
                {%- endif %}
                {%- if add_vision_id %}
                    {{- 'Video ' ~ video_count.value ~ ': ' }}
                {%- endif %}
                {{- '<|vision_start|><|video_pad|><|vision_end|>' }}
            {%- elif 'text' in item %}
                {{- item.text }}
            {%- else %}
                {{- raise_exception('Unexpected item type in content.') }}
            {%- endif %}
        {%- endfor %}
    {%- elif content is none or content is undefined %}
        {{- '' }}
    {%- else %}
        {{- raise_exception('Unexpected content type.') }}
    {%- endif %}
{%- endmacro %}
{%- if not messages %}
    {{- raise_exception('No messages provided.') }}
{%- endif %}
{%- if tools and tools is iterable and tools is not mapping %}
    {{- '<|im_start|>system\n' }}
    {{- "# Tools\n\nYou have access to the following functions:\n\n<tools>" }}
    {%- for tool in tools %}
        {{- "\n" }}
        {{- tool | tojson }}
    {%- endfor %}
    {{- "\n</tools>" }}
    {{- '\n\nIf you choose to call a function ONLY reply in the following format with NO suffix:\n\n<tool_call>\n<function=example_function_name>\n<parameter=example_parameter_1>\nvalue_1\n</parameter>\n<parameter=example_parameter_2>\nThis is the value for the second parameter\nthat can span\nmultiple lines\n</parameter>\n</function>\n</tool_call>\n\n<IMPORTANT>\nReminder:\n- Function calls MUST follow the specified format: an inner <function=...></function> block must be nested within <tool_call></tool_call> XML tags\n- Required parameters MUST be specified\n- You may provide optional reasoning for your function call in natural language BEFORE the function call, but NOT after\n- If there is no function call available, answer the question like normal with your current knowledge and do not tell the user about function calls\n</IMPORTANT>' }}
    {%- if messages[0].role == 'system' %}
        {%- set content = render_content(messages[0].content, false, true)|trim %}
        {%- if content %}
            {{- '\n\n' + content }}
        {%- endif %}
    {%- endif %}
    {{- '<|im_end|>\n' }}
{%- else %}
    {%- if messages[0].role == 'system' %}
        {%- set content = render_content(messages[0].content, false, true)|trim %}
        {{- '<|im_start|>system\n' + content + '<|im_end|>\n' }}
    {%- endif %}
{%- endif %}
{%- set ns = namespace(multi_step_tool=true, last_query_index=messages|length - 1) %}
{%- for message in messages[::-1] %}
    {%- set index = (messages|length - 1) - loop.index0 %}
    {%- if ns.multi_step_tool and message.role == "user" %}
        {%- set content = render_content(message.content, false)|trim %}
        {%- if not(content.startswith('<tool_response>') and content.endswith('</tool_response>')) %}
            {%- set ns.multi_step_tool = false %}
            {%- set ns.last_query_index = index %}
        {%- endif %}
    {%- endif %}
{%- endfor %}
{%- if ns.multi_step_tool %}
    {{- raise_exception('No user query found in messages.') }}
{%- endif %}
{%- for message in messages %}
    {%- set content = render_content(message.content, true)|trim %}
    {%- if message.role == "system" %}
        {%- if not loop.first %}
            {{- raise_exception('System message must be at the beginning.') }}
        {%- endif %}
    {%- elif message.role == "user" %}
        {{- '<|im_start|>' + message.role + '\n' + content + '<|im_end|>' + '\n' }}
    {%- elif message.role == "assistant" %}
        {%- set reasoning_content = '' %}
        {%- if message.reasoning_content is string %}
            {%- set reasoning_content = message.reasoning_content %}
        {%- else %}
            {%- if '</think>' in content %}
                {%- set reasoning_content = content.split('</think>')[0].rstrip('\n').split('<think>')[-1].lstrip('\n') %}
                {%- set content = content.split('</think>')[-1].lstrip('\n') %}
            {%- endif %}
        {%- endif %}
        {%- set reasoning_content = reasoning_content|trim %}
        {%- if loop.index0 > ns.last_query_index %}
            {{- '<|im_start|>' + message.role + '\n<think>\n' + reasoning_content + '\n</think>\n\n' + content }}
        {%- else %}
            {{- '<|im_start|>' + message.role + '\n' + content }}
        {%- endif %}
        {%- if message.tool_calls and message.tool_calls is iterable and message.tool_calls is not mapping %}
            {%- for tool_call in message.tool_calls %}
                {%- if tool_call.function is defined %}
                    {%- set tool_call = tool_call.function %}
                {%- endif %}
                {%- if loop.first %}
                    {%- if content|trim %}
                        {{- '\n\n<tool_call>\n<function=' + tool_call.name + '>\n' }}
                    {%- else %}
                        {{- '<tool_call>\n<function=' + tool_call.name + '>\n' }}
                    {%- endif %}
                {%- else %}
                    {{- '\n<tool_call>\n<function=' + tool_call.name + '>\n' }}
                {%- endif %}
                {%- if tool_call.arguments is defined %}
                    {%- for args_name, args_value in tool_call.arguments|items %}
                        {{- '<parameter=' + args_name + '>\n' }}
                        {%- set args_value = args_value | tojson | safe if args_value is mapping or (args_value is sequence and args_value is not string) else args_value | string %}
                        {{- args_value }}
                        {{- '\n</parameter>\n' }}
                    {%- endfor %}
                {%- endif %}
                {{- '</function>\n</tool_call>' }}
            {%- endfor %}
        {%- endif %}
        {{- '<|im_end|>\n' }}
    {%- elif message.role == "tool" %}
        {%- if loop.previtem and loop.previtem.role != "tool" %}
            {{- '<|im_start|>user' }}
        {%- endif %}
        {{- '\n<tool_response>\n' }}
        {{- content }}
        {{- '\n</tool_response>' }}
        {%- if not loop.last and loop.nextitem.role != "tool" %}
            {{- '<|im_end|>\n' }}
        {%- elif loop.last %}
            {{- '<|im_end|>\n' }}
        {%- endif %}
    {%- else %}
        {{- raise_exception('Unexpected message role.') }}
    {%- endif %}
{%- endfor %}
{%- if add_generation_prompt %}
    {{- '<|im_start|>assistant\n' }}
    {%- if enable_thinking is defined and enable_thinking is false %}
        {{- '<think>\n\n</think>\n\n' }}
    {%- else %}
        {{- '<think>\n' }}
    {%- endif %}
{%- endif %}

{%- set image_count = namespace(value=0) %}
{%- set video_count = namespace(value=0) %}
{%- macro render_content(content, do_vision_count, is_system_content=false) %}
    {%- if content is string %}
        {{- content }}
    {%- elif content is iterable and content is not mapping %}
        {%- for item in content %}
            {%- if 'image' in item or 'image_url' in item or item.type == 'image' %}
                {%- if is_system_content %}
                    {{- raise_exception('System message cannot contain images.') }}
                {%- endif %}
                {%- if do_vision_count %}
                    {%- set image_count.value = image_count.value + 1 %}
                {%- endif %}
                {%- if add_vision_id %}
                    {{- 'Picture ' ~ image_count.value ~ ': ' }}
                {%- endif %}
                {{- '<|vision_start|><|image_pad|><|vision_end|>' }}
            {%- elif 'video' in item or item.type == 'video' %}
                {%- if is_system_content %}
                    {{- raise_exception('System message cannot contain videos.') }}
                {%- endif %}
                {%- if do_vision_count %}
                    {%- set video_count.value = video_count.value + 1 %}
                {%- endif %}
                {%- if add_vision_id %}
                    {{- 'Video ' ~ video_count.value ~ ': ' }}
                {%- endif %}
                {{- '<|vision_start|><|video_pad|><|vision_end|>' }}
            {%- elif 'text' in item %}
                {{- item.text }}
            {%- else %}
                {{- raise_exception('Unexpected item type in content.') }}
            {%- endif %}
        {%- endfor %}
    {%- elif content is none or content is undefined %}
        {{- '' }}
    {%- else %}
        {{- raise_exception('Unexpected content type.') }}
    {%- endif %}
{%- endmacro %}
{%- if not messages %}
    {{- raise_exception('No messages provided.') }}
{%- endif %}
{%- if tools and tools is iterable and tools is not mapping %}
    {{- '<|im_start|>system\n' }}
    {{- "# Tools\n\nYou have access to the following functions:\n\n<tools>" }}
    {%- for tool in tools %}
        {{- "\n" }}
        {{- tool | tojson }}
    {%- endfor %}
    {{- "\n</tools>" }}
    {{- '\n\nIf you choose to call a function ONLY reply in the following format with NO suffix:\n\n<tool_call>\n<function=example_function_name>\n<parameter=example_parameter_1>\nvalue_1\n</parameter>\n<parameter=example_parameter_2>\nThis is the value for the second parameter\nthat can span\nmultiple lines\n</parameter>\n</function>\n</tool_call>\n\n<IMPORTANT>\nReminder:\n- Function calls MUST follow the specified format: an inner <function=...></function> block must be nested within <tool_call></tool_call> XML tags\n- Required parameters MUST be specified\n- You may provide optional reasoning for your function call in natural language BEFORE the function call, but NOT after\n- If there is no function call available, answer the question like normal with your current knowledge and do not tell the user about function calls\n</IMPORTANT>' }}
    {%- if messages[0].role == 'system' %}
        {%- set content = render_content(messages[0].content, false, true)|trim %}
        {%- if content %}
            {{- '\n\n' + content }}
        {%- endif %}
    {%- endif %}
    {{- '<|im_end|>\n' }}
{%- else %}
    {%- if messages[0].role == 'system' %}
        {%- set content = render_content(messages[0].content, false, true)|trim %}
        {{- '<|im_start|>system\n' + content + '<|im_end|>\n' }}
    {%- endif %}
{%- endif %}
{%- set ns = namespace(multi_step_tool=true, last_query_index=messages|length - 1) %}
{%- for message in messages[::-1] %}
    {%- set index = (messages|length - 1) - loop.index0 %}
    {%- if ns.multi_step_tool and message.role == "user" %}
        {%- set content = render_content(message.content, false)|trim %}
        {%- if not(content.startswith('<tool_response>') and content.endswith('</tool_response>')) %}
            {%- set ns.multi_step_tool = false %}
            {%- set ns.last_query_index = index %}
        {%- endif %}
    {%- endif %}
{%- endfor %}
{%- if ns.multi_step_tool %}
    {{- raise_exception('No user query found in messages.') }}
{%- endif %}
{%- for message in messages %}
    {%- set content = render_content(message.content, true)|trim %}
    {%- if message.role == "system" %}
        {%- if not loop.first %}
            {{- raise_exception('System message must be at the beginning.') }}
        {%- endif %}
    {%- elif message.role == "user" %}
        {{- '<|im_start|>' + message.role + '\n' + content + '<|im_end|>' + '\n' }}
    {%- elif message.role == "assistant" %}
        {%- set reasoning_content = '' %}
        {%- if message.reasoning_content is string %}
            {%- set reasoning_content = message.reasoning_content %}
        {%- else %}
            {%- if '</think>' in content %}
                {%- set reasoning_content = content.split('</think>')[0].rstrip('\n').split('<think>')[-1].lstrip('\n') %}
                {%- set content = content.split('</think>')[-1].lstrip('\n') %}
            {%- endif %}
        {%- endif %}
        {%- set reasoning_content = reasoning_content|trim %}
        {%- if loop.index0 > ns.last_query_index %}
            {{- '<|im_start|>' + message.role + '\n<think>\n' + reasoning_content + '\n</think>\n\n' + content }}
        {%- else %}
            {{- '<|im_start|>' + message.role + '\n' + content }}
        {%- endif %}
        {%- if message.tool_calls and message.tool_calls is iterable and message.tool_calls is not mapping %}
            {%- for tool_call in message.tool_calls %}
                {%- if tool_call.function is defined %}
                    {%- set tool_call = tool_call.function %}
                {%- endif %}
                {%- if loop.first %}
                    {%- if content|trim %}
                        {{- '\n\n<tool_call>\n<function=' + tool_call.name + '>\n' }}
                    {%- else %}
                        {{- '<tool_call>\n<function=' + tool_call.name + '>\n' }}
                    {%- endif %}
                {%- else %}
                    {{- '\n<tool_call>\n<function=' + tool_call.name + '>\n' }}
                {%- endif %}
                {%- if tool_call.arguments is defined %}
                    {%- for args_name, args_value in tool_call.arguments|items %}
                        {{- '<parameter=' + args_name + '>\n' }}
                        {%- set args_value = args_value | tojson if args_value is mapping or (args_value is iterable and args_value is not string) else args_value | string %}
                        {{- args_value }}
                        {{- '\n</parameter>\n' }}
                    {%- endfor %}
                {%- endif %}
                {{- '</function>\n</tool_call>' }}
            {%- endfor %}
        {%- endif %}
        {{- '<|im_end|>\n' }}
    {%- elif message.role == "tool" %}
        {%- if loop.previtem and loop.previtem.role != "tool" %}
            {{- '<|im_start|>user' }}
        {%- endif %}
        {{- '\n<tool_response>\n' }}
        {{- content }}
        {{- '\n</tool_response>' }}
        {%- if not loop.last and loop.nextitem.role != "tool" %}
            {{- '<|im_end|>\n' }}
        {%- elif loop.last %}
            {{- '<|im_end|>\n' }}
        {%- endif %}
    {%- else %}
        {{- raise_exception('Unexpected message role.') }}
    {%- endif %}
{%- endfor %}
{%- if add_generation_prompt %}
    {{- '<|im_start|>assistant\n' }}
    {%- if enable_thinking is defined and enable_thinking is false %}
        {{- '<think>\n\n</think>\n\n' }}
    {%- else %}
        {{- '<think>\n' }}
    {%- endif %}
{%- endif %}

